// MT2009_PLUS_YOHARA_PB_V1 (damage): Straznica Nemere (PB) - Metin Chlodu (PB) (8135) takes damage only from a
// Shaman, Kolumna Smoka Polnocy (PB) (20538) only from a Shaman or a Ninja (the pl-wiki; server-patches/przebudzeni).
// Every other blow - another class, a pet, poison or fire left by someone - is blocked.
if (IsStone() && (GetRaceNum() == 8135 || GetRaceNum() == 20538))
{
	const bool bAllowed = pAttacker && pAttacker->IsPC() &&
		(pAttacker->GetJob() == JOB_SHAMAN || (GetRaceNum() == 20538 && pAttacker->GetJob() == JOB_ASSASSIN));
	if (!bAllowed)
	{
		if (pAttacker)
		{
			SendDamagePacket(pAttacker, 0, DAMAGE_BLOCK);
			if (pAttacker->IsPC() && type == DAMAGE_TYPE_NORMAL)
				pAttacker->ChatPacket(CHAT_TYPE_INFO, GetRaceNum() == 8135 ? "Ten Metin moze zranic tylko Szaman." : "Te Kolumne moze zranic tylko Ninja albo Szaman.");
		}
		return false;
	}
}

